package com.gymmind.knowledge.application;
import com.gymmind.ai.domain.*; import com.gymmind.knowledge.infrastructure.search.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.shared.security.CurrentActor; import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class KnowledgeSearchServiceTest { @Test void searchesTenantAndCapsResults(){var k=mock(KeywordIndexPort.class);var v=mock(VectorIndexPort.class);var e=mock(EmbeddingGateway.class);var q=mock(com.gymmind.tenancy.application.TenantQuotaService.class);when(e.embed(any())).thenReturn(List.of(new float[1024]));var xs=new ArrayList<IndexedChunk>();for(int i=0;i<10;i++)xs.add(new IndexedChunk("c"+i,7L,"text",new float[1024]));when(k.search("q",7L,1L)).thenReturn(xs);when(v.search(any(),eq(7L),eq(1L))).thenReturn(List.of());var s=new DefaultKnowledgeSearchService(k,v,e,null,q);assertThat(s.search(actor(7L),"q")).hasSize(8);} @Test void rerankerOrderIsAppliedToMergedCandidates(){var k=mock(KeywordIndexPort.class);var v=mock(VectorIndexPort.class);var e=mock(EmbeddingGateway.class);var q=mock(com.gymmind.tenancy.application.TenantQuotaService.class);var r=mock(com.gymmind.ai.domain.RerankGateway.class);when(e.embed(any())).thenReturn(List.of(new float[1024]));when(k.search("q",7L,1L)).thenReturn(List.of(new IndexedChunk("c1",7L,"first",new float[1024]),new IndexedChunk("c2",7L,"second",new float[1024])));when(v.search(any(),eq(7L),eq(1L))).thenReturn(List.of());when(r.rerank(eq("q"),any())).thenReturn(List.of(new com.gymmind.ai.domain.RankedChunk("c2",1),new com.gymmind.ai.domain.RankedChunk("c1",2)));var result=new DefaultKnowledgeSearchService(k,v,e,r,q).search(actor(7L),"q");assertThat(result).extracting(com.gymmind.ai.domain.ContextSegment::id).containsExactly("c2","c1");} @Test void platformReturnsEmptyWhenNoDocuments(){var s=new DefaultKnowledgeSearchService(mock(KeywordIndexPort.class),mock(VectorIndexPort.class),mock(EmbeddingGateway.class),null,mock(com.gymmind.tenancy.application.TenantQuotaService.class));assertThat(s.search(platform(),"q")).isEmpty();} @Test void rejectsWhenKnowledgeModuleIsDisabled(){var quotas=mock(com.gymmind.tenancy.application.TenantQuotaService.class);var s=new DefaultKnowledgeSearchService(mock(KeywordIndexPort.class),mock(VectorIndexPort.class),mock(EmbeddingGateway.class),null,quotas);org.mockito.Mockito.doThrow(new com.gymmind.shared.error.BusinessException(com.gymmind.shared.error.ErrorCode.CONFLICT,"知识库模块未开通")).when(quotas).ensureKnowledgeModuleEnabled(7L);assertThatThrownBy(()->s.search(actor(7L),"q")).isInstanceOf(com.gymmind.shared.error.BusinessException.class);} private CurrentActor actor(long t){return new CurrentActor(1L,t,Set.of(RoleCode.GYM_ADMIN),Set.of("knowledge:read"),0,"t");} private CurrentActor platform(){return new CurrentActor(1L,null,Set.of(RoleCode.PLATFORM_ADMIN),Set.of(),0,"t");} }
